// Server-backed, numbered seats replace the illustrative attendee pagination.
let viewedHall=null,pickedDesk=null;const zoneOf=n=>n<=12?'도서관':n<=24?'창가':'모닥불';
interior.classList.add('seat-plan-mode');interior.querySelector('.interior-heading h2').textContent='빈 의자를 골라, 함께 앉아요';interior.querySelector('.interior-heading p').textContent='한 공부방에 30석. 공부 시작을 누르면 선택한 자리가 확정돼요.';
const seatTools=document.createElement('div');seatTools.className='seat-tools';seatTools.innerHTML='<nav id="studyHalls" aria-label="학급 공부방 선택"></nav><p id="deskNotice" role="status"></p><div class="seat-legend"><span>□ 빈자리</span><span>📖 집중 중</span><span>☕ 휴식 · 자리 유지</span><span>✦ 내 자리</span></div>';interior.querySelector('.cafe-floor').before(seatTools);
interior.querySelectorAll('.reading-tables,.window-desks,.fireside-furniture,.room-select,.lounge-furniture').forEach(e=>e.hidden=true);
interior.querySelector('.interior-caption').textContent='각 공부방은 30석입니다. 휴식 중에도 자리를 유지하며, 공부를 마치면 반환됩니다. 연결이 15분 이상 끊기면 자리는 반환되고 공부 기록은 남아요.';
$('#studySeat').closest('label').hidden=true;$('#studyStart button').textContent='선택한 자리에서 공부 시작';
const baseDeskDisplay=display;display=function(d){baseDeskDisplay(d)};
renderSeatedFriends=function(){if(data)drawSeatPlan()};
function stationHTML(person,number,rest=false){return '<span class="friend-station '+(rest?'resting':'')+'" data-peer="'+escape(person.actor)+'" data-pose="'+(rest?'resting':'reading')+'" style="--shirt:'+['#88adc2','#d6a36d','#9daf87','#b899bb'][number%4]+'"><span class="seat-back" aria-hidden="true"></span>'+avatarMarkup()+'<span class="personal-desk" aria-hidden="true"><i class="personal-lamp"></i><i class="personal-book"></i><i class="tea-cup">☕</i></span><span class="friend-name">'+escape(person.name)+'</span><small class="friend-class">'+escape(data.rooms.find(r=>r.id===person.home)?.label||'우리 반')+'</small></span>'}
function drawSeatPlan(){if(!data)return;const halls=data.rooms||[],current=data.current;if(!halls.some(r=>r.id===viewedHall))viewedHall=current?.studyRoom||data.home;const hall=halls.find(r=>r.id===viewedHall),seats=(data.seats||[]).filter(s=>s.studyRoom===viewedHall);const own=(data.seats||[]).find(s=>s.actor===data.actor);const foreign=viewedHall!==data.home,allowed=data.library&&!data.paused&&!hall?.paused&&(!foreign||(data.travel&&data.passport));
if(pickedDesk&&pickedDesk.room===viewedHall&&seats.some(s=>s.number===pickedDesk.number&&s.actor!==data.actor))pickedDesk=null;
$('#studyHalls').innerHTML=halls.map(r=>`<button data-hall="${r.id}" class="${r.id===viewedHall?'selected':''}" aria-pressed="${r.id===viewedHall}"><b>${escape(r.label)}</b><small>${(data.seats||[]).filter(s=>s.studyRoom===r.id).length} / 30석 · ${r.id===data.home?'우리 반':'이웃 반'}</small></button>`).join('');
$('#deskNotice').textContent=current&&!current.seatNumber?'기존 공부 기록은 유지돼요. 빈자리를 다시 골라 앉은 뒤 집중을 이어가 주세요.':!allowed?(foreign&&!data.passport?'이웃 반에 앉으려면 여권을 먼저 발급해 주세요.':foreign&&!data.travel?'선생님이 여행을 열면 이웃 반 공부방에 앉을 수 있어요.':'지금은 공부방이 쉬는 시간이에요.'):pickedDesk?'선택: '+(halls.find(r=>r.id===pickedDesk.room)?.label||'공부방')+' '+pickedDesk.number+'번 · 아래에서 목표를 적고 공부 시작을 눌러 확정하세요.':own?'내 자리: '+(halls.find(r=>r.id===own.studyRoom)?.label||'공부방')+' '+own.number+'번 · '+own.status:seats.length===30?'이 공부방은 만석이에요. 다른 공부방의 빈자리를 확인해 주세요.':'빈 의자를 누르면 공부할 자리를 선택할 수 있어요.';
const oldPos=new Map();interior.querySelectorAll('.friend-station[data-peer]').forEach(n=>{const a=n.querySelector('.seated-avatar');if(a&&a.getClientRects().length)oldPos.set(n.dataset.peer,{rect:a.getBoundingClientRect(),rest:n.dataset.pose==='resting'})});
for(const [id,start,end]of [['libraryPeople',1,12],['windowPeople',13,24],['firePeople',25,30]]){const host=$('#'+id);host.className='numbered-room';host.parentElement.classList.add('has-seated-friends');host.innerHTML=Array.from({length:end-start+1},(_,i)=>{const n=i+start,p=seats.find(s=>s.number===n),mine=p?.actor===data.actor,selected=pickedDesk?.room===viewedHall&&pickedDesk.number===n;return `<button data-desk="${n}" class="numbered-seat ${p?'occupied':'vacant'} ${mine?'mine':''} ${selected?'picked':''}" ${p&&!mine||!allowed||current?.seatNumber&&!mine?'disabled':''} aria-label="${n}번 ${p?escape(p.name)+' · '+escape(p.status):'빈자리'}${mine?' · 내 자리':''}"><span class="desk-number">${mine?'✦ ':''}${n}번</span>${p?(p.status==='집중 중'?stationHTML(p,n):`<span class="reserved-desk"><span>☕</span><b>${escape(p.name)}</b><small>라운지 · 자리 유지</small></span>`):'<span class="empty-chair" aria-hidden="true"></span><span class="empty-table" aria-hidden="true">▤</span><span class="vacant-label">'+(selected?'선택됨':'앉기')+'</span>'}</button>`}).join('')}
const lounge=$('#loungePeople');lounge.className='numbered-room lounge-seats';const resting=seats.filter(p=>p.status==='쉬는 중');lounge.innerHTML=resting.length?resting.map(p=>stationHTML(p,p.number,true)).join(''):'<span class="room-empty">공부하다 쉬고 싶으면 라운지로 오세요.</span>';lounge.parentElement.classList.add('has-seated-friends');
for(const node of interior.querySelectorAll('.friend-station[data-peer]')){const old=oldPos.get(node.dataset.peer),a=node.querySelector('.seated-avatar'),rect=a.getBoundingClientRect();if(movingFriends.has(node.dataset.peer))a.style.visibility='hidden';if(old&&old.rest!==(node.dataset.pose==='resting')&&rect.width&&!interior.classList.contains('still-cafe')&&!document.hidden)walkToSeat(node.dataset.peer,a,old.rect,rect)}
$('#studyStart button').disabled=!pickedDesk||!allowed||busy;$('#myRoomState').textContent=own?`${own.number}번 · ${own.status}`:current?'빈자리 다시 선택':'30석 중 빈자리 선택';$('#pauseStudy').disabled=!!current&&!current.seatNumber||!data.library||data.paused;$('#loungeAction').disabled=!!current&&!current.seatNumber;
window.library3D?.update({seats,actor:data.actor,pickedDesk,allowed,current,viewedHall});
}
$('#studyHalls').onclick=e=>{const b=e.target.closest('[data-hall]');if(!b)return;viewedHall=b.dataset.hall;pickedDesk=null;drawSeatPlan()};
interior.addEventListener('click',async e=>{const b=e.target.closest('[data-desk]');if(!b||b.disabled)return;if(busy){message('저장을 확인 중이에요. 잠시 뒤 다시 눌러 주세요.');return}const number=Number(b.dataset.desk);if(data.current?.seatNumber){$('.focus-card').scrollIntoView({behavior:'smooth',block:'center'});return}if(data.current){const d=await act('/api/campus/study',{action:'claim',id:data.current.id,studyRoom:viewedHall,seatNumber:number});if(d){pickedDesk=null;drawSeatPlan();message('자리를 다시 확보했어요. 다시 집중을 눌러 이어가세요.')}return}pickedDesk={room:viewedHall,number};$('#studySeat').value=zoneOf(number);drawSeatPlan();$('.focus-card').scrollIntoView({behavior:'smooth',block:'center'});$('#studyGoal').focus({preventScroll:true})});
$('#studyStart').onsubmit=async e=>{e.preventDefault();if(demo){message('실제 좌석 배정은 학급 코드로 입장한 뒤 사용할 수 있어요.');return}if(!pickedDesk){message('먼저 빈 의자를 선택해 주세요.');return}const choice={...pickedDesk},id=sessionStorage.getItem('study-start-id')||crypto.randomUUID();sessionStorage.setItem('study-start-id',id);const d=await act('/api/campus/study',{action:'start',id,goal:$('#studyGoal').value,plan:Number($('#studyPlan').value),seat:zoneOf(choice.number),studyRoom:choice.room,seatNumber:choice.number});if(d){sessionStorage.removeItem('study-start-id');pickedDesk=null;viewedHall=d.current?.studyRoom||viewedHall;drawSeatPlan();message(choice.number+'번 자리에 앉았어요. 함께 집중해요.')}else{await refresh();drawSeatPlan()}};
const baseSeatRefresh=refresh;refresh=async function(){await baseSeatRefresh();if(data)drawSeatPlan()};
if(data)drawSeatPlan();
